/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { ConfigurationDetectiveScreen } from "../../src/configuration-detective/ConfigurationDetectiveScreen.js";
import ElectronConfigurationColors from "../../src/ElectronConfigurationColors.js";
import { FillTheOrbitalsScreen } from "../../src/fill-orbitals/FillTheOrbitalsScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { MakeAnIonScreen } from "../../src/ions/MakeAnIonScreen.js";
import { PatternsInTheTableScreen } from "../../src/periodic-patterns/PatternsInTheTableScreen.js";
import { ElectronConfigurationPreferencesModel } from "../../src/preferences/ElectronConfigurationPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from electronConfigurationQueryParameters.
  const simPreferences = new ElectronConfigurationPreferencesModel();

  const screens = [
    new FillTheOrbitalsScreen(
      {
        name: stringManager.getScreenNames().fillOrbitalsStringProperty,
        tandem: Tandem.ROOT.createTandem("fillOrbitalsScreen"),
        backgroundColorProperty: ElectronConfigurationColors.backgroundColorProperty,
      },
      simPreferences.tableExtentProperty,
    ),
    new PatternsInTheTableScreen(
      {
        name: stringManager.getScreenNames().periodicPatternsStringProperty,
        tandem: Tandem.ROOT.createTandem("periodicPatternsScreen"),
        backgroundColorProperty: ElectronConfigurationColors.backgroundColorProperty,
      },
      simPreferences.tableExtentProperty,
    ),
    new MakeAnIonScreen(
      {
        name: stringManager.getScreenNames().ionsStringProperty,
        tandem: Tandem.ROOT.createTandem("ionsScreen"),
        backgroundColorProperty: ElectronConfigurationColors.backgroundColorProperty,
      },
      simPreferences.tableExtentProperty,
    ),
    new ConfigurationDetectiveScreen(
      {
        name: stringManager.getScreenNames().configurationDetectiveStringProperty,
        tandem: Tandem.ROOT.createTandem("configurationDetectiveScreen"),
        backgroundColorProperty: ElectronConfigurationColors.backgroundColorProperty,
      },
      simPreferences.tableExtentProperty,
    ),
  ];

  return { screens, tracked: { ElectronConfigurationColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
